data "terraform_remote_state" "red" {
  backend = "gcs"
  config = {
    bucket = "tienda-tfstate-pro"
    prefix = "red"
  }
}

resource "google_container_cluster" "pro" {
  name       = "gke-pro"
  location   = "europe-west1"
  subnetwork = data.terraform_remote_state.red.outputs.subred_id
}
